"""The identity hash: a claim's root, and the build digest over generated bytes.

`root` and `build_digest` are the canonical serialization pinned by
`spec/identity.md`. `root` hashes a string-to-string map built from the
recipe's canonical JSON, the pinned inputs, and every non-generated step
output; `build_digest` hashes the sorted `[output, sha256]` pairs of every
*present* generated-class produce step, except one carrying a `from` key
(it names a step whose bytes are supplied by another claim, not grown here).
`_preimage_recipe` applies the format-3 guidance strip and the format-4 step
canonicalization before the recipe enters the root; `_parts` and
`_claim_format` are the seams between them.
"""
import hashlib
import json
import os

from . import core
from . import recipe as recipe_module
from .core import ClaimError


def _canonical_json(obj) -> str:
    """`json.dumps(obj, sort_keys=True)` at its defaults: ASCII-escaped,
    default separators (`", "` / `": "`) -- exactly spec/identity.md's rule."""
    try:
        return json.dumps(obj, sort_keys=True)
    except TypeError as exc:
        raise ClaimError(
            f"recipe contains a value with no canonical JSON form "
            f"(TOML date/time values are refused at sealing): {exc}"
        ) from exc


def _claim_format(recipe: dict) -> int:
    """The claim's declared format; absent means 1 (spec/claim-format.md)."""
    return recipe.get("claim", {}).get("format", 1)


def _preimage_recipe(recipe: dict) -> dict:
    """The recipe exactly as it enters the root preimage.

    At format >= 3, every step's `guidance`/`request` key is stripped --
    producer guidance cannot decide acceptance, so it is not identity-bearing
    (spec/identity.md). At format >= 4, the stripped steps are reordered into
    the lexicographic order of their own canonical JSON encodings, so the
    step list is a set rather than authoring-order text. Formats 1-2 pass the
    step list through untouched, byte for byte.
    """
    fmt = _claim_format(recipe)
    steps = [dict(s) for s in recipe.get("step", [])]
    if fmt >= 3:
        steps = [
            {k: v for k, v in s.items() if k not in core.GUIDANCE_KEYS}
            for s in steps
        ]
    if fmt >= 4:
        steps.sort(key=_canonical_json)

    preimage = dict(recipe)
    if "step" in recipe or steps:
        preimage["step"] = steps
    return preimage


def _parts(recipe: dict, d: str) -> dict:
    """The string-to-string map the root hashes (spec/identity.md)."""
    parts = {
        "digest": core.DIGEST,
        "recipe": _canonical_json(_preimage_recipe(recipe)),
    }
    for path in recipe_module._inputs(recipe, d):
        parts["input:" + path] = core._hash_file(core._safe(d, path))
    for step in recipe_module._steps(recipe):
        kind = step.get("kind")
        klass = step.get("class", "generated" if kind == "produce" else "pinned")
        if klass == "generated":
            continue
        output = step.get("output")
        if not output:
            continue
        parts["pinned:" + output] = core._hash_file(core._safe(d, output))
    return parts


def root(recipe: dict, d: str) -> str:
    """The claim's identity: sha256 of the canonical `parts` map."""
    return hashlib.sha256(_canonical_json(_parts(recipe, d)).encode("utf-8")).hexdigest()


def build_digest(d: str) -> str:
    """The digest a signature binds: sha256 over the present generated bytes.

    Every `produce` step whose class is `generated` (the default) and which
    carries no `from` key contributes its output's path and sha256 if the
    file is present on disk; an absent generated output is simply omitted,
    never an error. The empty list digests the claim with no generated
    bytes at all (spec/vectors/README.md: rd1-rd6).
    """
    parsed = recipe_module.load_recipe(d)
    pairs = []
    for step in recipe_module.produces(parsed):
        if step.get("class", "generated") != "generated":
            continue
        if "from" in step:
            continue
        output = step.get("output")
        path = core._safe(d, output)
        if not os.path.isfile(path):
            continue
        pairs.append([output, core._hash_file(path)])
    pairs.sort(key=lambda pair: pair[0])
    return hashlib.sha256(_canonical_json(pairs).encode("utf-8")).hexdigest()
